import{_ as s,o as n,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"47. Command-Line Arguments (argc, argv)","description":"The Little Book of C — 47. Command-Line Arguments (argc, argv)","frontmatter":{"title":"47. Command-Line Arguments (argc, argv)","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Input Output and Files"],"description":"The Little Book of C — 47. Command-Line Arguments (argc, argv)","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":47,"sidebarWeight":47,"lang":"en-US","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/047-Command-Line Arguments (argc, argv)","alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/047-Command-Line Arguments (argc, argv)"},"headers":[],"relativePath":"posts/c教程/en-US/05-Input Output and Files/047-Command-Line Arguments (argc, argv).md","filePath":"posts/c教程/en-US/05-Input Output and Files/047-Command-Line Arguments (argc, argv).md","lastUpdated":1790163617000}'),p={name:"posts/c教程/en-US/05-Input Output and Files/047-Command-Line Arguments (argc, argv).md"};function i(l,a,o,c,r,d){return n(),e("div",null,[...a[0]||(a[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/05-输入输出与文件/047-Command-Line Arguments (argc, argv))</p><p>Every C program can receive input directly from the command line, no<code>scanf</code>, no<code>fgets</code>, just arguments passed when you run the executable. This is how professional C tools (like<code>gcc</code>,<code>ls</code>, and<code>grep</code>) receive filenames, options, and flags.</p><h4 id="the-function-signature" tabindex="-1">The Function Signature <a class="header-anchor" href="#the-function-signature" aria-label="Permalink to &quot;The Function Signature&quot;">​</a></h4><p>Your<code>main</code> function can take two parameters:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int main(int argc, char *argv[])</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Meaning</th></tr></thead><tbody><tr><td><code>argc</code></td><td>Argument count (number of command-line arguments)</td></tr><tr><td><code>argv</code></td><td>Argument vector (array of C strings, each argument)</td></tr></tbody></table><p><code>argv[0]</code> is the program name itself, and<code>argv[1]</code> onward are the user-provided arguments.</p><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./hello world test</span></span></code></pre></div><p>Then:</p><ul><li><code>argc == 3</code></li><li><code>argv[0] = &quot;./hello&quot;</code></li><li><code>argv[1] = &quot;world&quot;</code></li><li><code>argv[2] = &quot;test&quot;</code></li></ul><h4 id="tiny-code-print-command-line-arguments" tabindex="-1">Tiny Code: Print Command-Line Arguments <a class="header-anchor" href="#tiny-code-print-command-line-arguments" aria-label="Permalink to &quot;Tiny Code: Print Command-Line Arguments&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    printf(&quot;Argument count: %d\\n&quot;, argc);</span></span>
<span class="line"><span>    for (int i = 0; i &lt; argc; i++)</span></span>
<span class="line"><span>        printf(&quot;argv[%d] = %s\\n&quot;, i, argv[i]);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./args foo bar 123</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Argument count: 4</span></span>
<span class="line"><span>argv[0] = ./args</span></span>
<span class="line"><span>argv[1] = foo</span></span>
<span class="line"><span>argv[2] = bar</span></span>
<span class="line"><span>argv[3] = 123</span></span></code></pre></div><h4 id="checking-for-missing-arguments" tabindex="-1">Checking for Missing Arguments <a class="header-anchor" href="#checking-for-missing-arguments" aria-label="Permalink to &quot;Checking for Missing Arguments&quot;">​</a></h4><p>If your program needs arguments, check<code>argc</code> before accessing them.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    if (argc &lt; 2) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Usage: %s &lt;filename&gt;\\n&quot;, argv[0]);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    printf(&quot;Opening file: %s\\n&quot;, argv[1]);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./fileop</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Usage: ./fileop &lt;filename&gt;</span></span></code></pre></div><p>Run again:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./fileop data.txt</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Opening file: data.txt</span></span></code></pre></div><h4 id="converting-string-arguments-to-numbers" tabindex="-1">Converting String Arguments to Numbers <a class="header-anchor" href="#converting-string-arguments-to-numbers" aria-label="Permalink to &quot;Converting String Arguments to Numbers&quot;">​</a></h4><p>All command-line arguments are strings. To use them as numbers, convert using:</p><ul><li><code>atoi()</code>– string to int</li><li><code>atof()</code>– string to float</li><li><code>strtol()</code>/<code>strtod()</code>– safer and more flexible alternatives</li></ul><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    if (argc != 3) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Usage: %s &lt;a&gt; &lt;b&gt;\\n&quot;, argv[0]);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    int a = atoi(argv[1]);</span></span>
<span class="line"><span>    int b = atoi(argv[2]);</span></span>
<span class="line"><span>    printf(&quot;%d + %d = %d\\n&quot;, a, b, a + b);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./sum 10 25</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10 + 25 = 35</span></span></code></pre></div><h4 id="handling-options-flags" tabindex="-1">Handling Options (Flags) <a class="header-anchor" href="#handling-options-flags" aria-label="Permalink to &quot;Handling Options (Flags)&quot;">​</a></h4><p>You can build simple command-line tools that handle options manually:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    int verbose = 0;</span></span>
<span class="line"><span>    for (int i = 1; i &lt; argc; i++) {</span></span>
<span class="line"><span>        if (strcmp(argv[i], &quot;-v&quot;) == 0)</span></span>
<span class="line"><span>            verbose = 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    if (verbose)</span></span>
<span class="line"><span>        printf(&quot;Verbose mode on\\n&quot;);</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        printf(&quot;Run quietly\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./tool -v</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Verbose mode on</span></span></code></pre></div><h4 id="tiny-code-mini-file-echo-tool" tabindex="-1">Tiny Code: Mini File Echo Tool <a class="header-anchor" href="#tiny-code-mini-file-echo-tool" aria-label="Permalink to &quot;Tiny Code: Mini File Echo Tool&quot;">​</a></h4><p>This program prints the content of a file passed as an argument:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    if (argc != 2) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Usage: %s &lt;file&gt;\\n&quot;, argv[0]);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    FILE *fp = fopen(argv[1], &quot;r&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Error&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char buf[128];</span></span>
<span class="line"><span>    while (fgets(buf, sizeof(buf), fp))</span></span>
<span class="line"><span>        printf(&quot;%s&quot;, buf);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./echo mytext.txt</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p><code>argc</code> and<code>argv</code> make your C programs scriptable and composable:</p><ul><li>Automate tasks from the command line</li><li>Integrate with shell scripts or pipelines</li><li>Process multiple input files</li><li>Implement command-line flags and options</li></ul><p>Every real-world C utility, from<code>ls</code> to<code>gcc</code>, depends on this pattern.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Write a program that takes a list of integers and prints their sum.</p><p>Add a<code>-r</code> flag to reverse the order of printed arguments.</p><p>Build a “greet” tool:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./greet Alice Bob Charlie</span></span></code></pre></div><p>→<code>Hello, Alice! Hello, Bob! Hello, Charlie!</code></p><p>Write a “compare” tool that checks if two file names are identical.</p><p>Combine<code>argc</code> and file I/O: copy one file to another with</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./copy source.txt dest.txt</span></span></code></pre></div><p>With command-line arguments, your C programs evolve from static exercises to flexible, real-world tools. Next, you’ll explore reading configuration files, a powerful way to let your programs adapt automatically without recompilation.</p>`,63)])])}const h=s(p,[["render",i]]);export{u as __pageData,h as default};
